from pathlib import Path
from PIL import Image, ImageOps
import json,hashlib,zipfile
p=Path(__file__).resolve().parent
h=lambda f:hashlib.sha256(f.read_bytes()).hexdigest()
rows=[('tren-patio-zipaquira.jpg','tren-patio-original-v5.webp',True),('estacion-juanperiodista-2018.jpg','estacion-original-2018-v5.webp',False),('estacion-vagon-p464thomas-2011.jpg','vagon-original-2011-v5.webp',False)]
assets=[]
for ref,name,crop in rows:
    original=p/'referencias-autorizadas'/ref;out=p/'imagenes/web'/name
    image=Image.open(original).convert('RGB')
    image=ImageOps.fit(image,(960,640),centering=(.5,.5)) if crop else image.copy()
    if not crop:image.thumbnail((960,720))
    image.save(out,'WEBP',quality=86,method=6)
    assets.append({'reference':ref,'reference_sha256':h(original),'web':'imagenes/web/'+name,'web_sha256':h(out),'dimensions':list(image.size),'bytes':out.stat().st_size,'changes':'Solo recorte3:2, reducción y compresión; sin alteración tonal ni reconstrucción' if crop else 'Solo reducción y compresión; sin recorte, alteración tonal o reconstrucción'})
d=json.loads((p/'paquete-destino-correcciones-v4.json').read_text())
train=next(x for x in d['places'] if x['slug']=='tren-sabana')
train['image'].update(file='images/tren-patio-original-v5.webp',image_origin='external',image_creator='Nils Öberg',image_source_url='https://commons.wikimedia.org/wiki/File:Zipaquira_station_yard.JPG',image_license='CC BY-SA 3.0',image_license_url='https://creativecommons.org/licenses/by-sa/3.0/',alt={'es':'Fotografía histórica del tren en el patio ferroviario de Zipaquirá','en':'Historical photograph of the train in the Zipaquirá railway yard','pt-BR':'Fotografia histórica do trem no pátio ferroviário de Zipaquirá'})
raw=(json.dumps(d,ensure_ascii=False,indent=2)+'\n').encode()
(p/'paquete-destino-comparacion-v5.json').write_bytes(raw)
with zipfile.ZipFile(p/'paquete-destino-correcciones-v4.zip') as old, zipfile.ZipFile(p/'paquete-destino-comparacion-v5.zip','w',zipfile.ZIP_DEFLATED) as out:
    out.writestr('paquete-destino.json',raw)
    for ref in [d['hero_image']['file']]+[x['image']['file'] for x in d['places']]:out.writestr(ref,(p/'imagenes/web'/Path(ref).name).read_bytes() if ref=='images/tren-patio-original-v5.webp' else old.read(ref))
html='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Zipaquirá · comparación ferroviaria</title><style>body{font:16px system-ui;background:#f6f7f8;color:#28323b;max-width:1200px;margin:auto;padding:24px}section{border-top:1px solid #ccd2d8;padding:20px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}img{width:100%;height:330px;object-fit:contain;background:#e5e8eb}figure{margin:0}h1{font-size:1.5rem}h2{font-size:1.15rem}a{color:#345a78}@media(max-width:650px){.pair{grid-template-columns:1fr}img{height:auto}}</style><h1>Comparación ferroviaria · Zipaquirá</h1><p>Propuestas para revisión. Ninguna foto histórica acredita material o estado actual. No se han aplicado cambios desde este subproceso.</p><section><h2>1. Tren: referencia real frente a ilustración rechazada</h2><div class="pair"><figure><img src="imagenes/web/tren-patio-original-v5.webp"><figcaption><b>Propuesta: fotografía original optimizada.</b> Patio ferroviario de Zipaquirá, Nils Öberg, CC BY-SA3.0. Fecha declarada2007/EXIF2003. Mismo entorno y material, sin embellecimiento IA.</figcaption></figure><figure><img src="imagenes/web/tren-patio-fiel-v4.webp"><figcaption><b>V4 rechazada.</b> La IA intensificó azul del cielo y contraste, limpió edificios, simplificó mecanismos y embelleció la escena. La fuente colombiana no basta para aprobar la identidad visual del derivado.</figcaption></figure></div><p><a href="https://commons.wikimedia.org/wiki/File:Zipaquira_station_yard.JPG">Fuente original</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/">Licencia</a></p></section><section><h2>2. Estación: fachada real, sin tren inventado</h2><div class="pair"><figure><img src="imagenes/web/estacion-original-2018-v5.webp"><figcaption>Referencia2018 de JuanPeriodista, CC BY-SA4.0. Edificio, parque y colores reales; no muestra vías ni tren. No resuelve por sí sola la solicitud de contexto ferroviario conjunto.</figcaption></figure><figure><img src="imagenes/web/estacion-fiel-v2.webp"><figcaption>Ilustración anterior de fachada. Tiene identidad del edificio pero no contexto ferroviario; no se presenta como corrección suficiente.</figcaption></figure></div><p><a href="https://commons.wikimedia.org/wiki/File:Estaci%C3%B3n_TREN_Zipaquir%C3%A1.jpg">Fuente2018</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/">Licencia</a></p></section><section><h2>3. Contexto ferroviario documentado: vagón expuesto</h2><img src="imagenes/web/vagon-original-2011-v5.webp"><p>Fotografía de P464thomas, 2-01-2011, CC BY-SA3.0. Vagón estático expuesto en la estación; no prueba servicio actual y no muestra la fachada completa. No se fusiona con otra foto para fingir ubicación.</p><a href="https://commons.wikimedia.org/wiki/File:Static_train_coach_exhibition_at_Zipaquira_station_on_2.January_2011..JPG">Fuente</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/">Licencia</a></section><p>La foto ferroviaria no determina por sí misma si un viaje concreto operará; la oferta actual se comprueba por separado con el operador.</p></html>'''
(p/'comparacion-ferroviaria-v5.html').write_text(html)
report={'date':'2026-10-20','destination':'zipaquira','assets':assets,'train_original_used_without_ai':True,'v4_rejected':True,'station_building_plus_train_same_photo_found':False,'station_request_complete':False,'human_approved':False,'preprod_imported':False,'production_changed':False,'candidate_zip_sha256':h(p/'paquete-destino-comparacion-v5.zip'),'integration_note':'Aplicar solo imagen y metadatos tren si coordinador modificó Catedral después de V4; no pisar crop actual.'}
(p/'COMPARACION_FERROVIARIA_V5.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(report,ensure_ascii=False,indent=2))
